<?php
declare(strict_types=1);
require __DIR__.'/fixtures.php';
use Zinema\Catalogue\{Context,Controller,FixedWindowLimiter,Query};
$cases=[];
$cases['default public factory returns not configured without data']=function(){ $r=\Zinema\Catalogue\Factory::unconfigured()->handle('GET',[]);apiAssert($r->status===503&&!str_contains($r->body,'Fictional')); };
$cases['public metadata browse excludes private access rules']=function(){ $r=apiCall(apiWorld(),['resource'=>'movies']);apiAssert($r['status']===200&&apiIds($r)===['501','502']); };
$cases['exact and partial case insensitive title search']=function(){ $w=apiWorld();apiAssert(apiIds(apiCall($w,['q'=>'aLpHa']))===['501']&&apiIds(apiCall($w,['q'=>'Fictional Alpha']))===['501']); };
$cases['unknown title is an empty result']=function(){ $r=apiCall(apiWorld(),['q'=>'nonexistent title']);apiAssert($r['status']===200&&apiIds($r)===[]&&$r['body']['data']['nextCursor']===null); };
$cases['empty normalized query browses safely']=function(){apiAssert(count(apiIds(apiCall(apiWorld(),['resource'=>'movies','q'=>'   '])))===2);};
$cases['Unicode title matching is supported']=function(){ $r=apiRecord('movie','501','සිනමා Fictional 演示');$w=apiWorld(null,[$r]);apiAssert(apiIds(apiCall($w,['q'=>'演示']))===['501']); };
$cases['percent underscore and quote are literal search characters']=function(){ $r=apiRecord('movie','501',"Fictional 50%_ ' Story");$w=apiWorld(null,[$r]);apiAssert(apiIds(apiCall($w,['q'=>"%_ '"]))===['501']); };
foreach(['genre'=>'drama','language'=>'si','release_year'=>'2026','max_runtime'=>'600','content_type'=>'movie'] as $key=>$value)$cases['validated filter '.$key]=function()use($key,$value){$r=apiCall(apiWorld(),['resource'=>'movies',$key=>$value]);apiAssert($r['status']===200&&apiIds($r)===['501','502']);};
$cases['combined filters preserve eligible matches']=function(){ $r=apiCall(apiWorld(),['q'=>'Alpha','genre'=>'drama','language'=>'si','release_year'=>'2026','max_runtime'=>'600','content_type'=>'movie']);apiAssert(apiIds($r)===['501']); };
$cases['runtime boundary excludes longer titles']=function(){apiAssert(apiIds(apiCall(apiWorld(),['resource'=>'movies','max_runtime'=>'599']))===[]);};
foreach(['sort'=>'popularity','genre'=>'unknown','language'=>'xx','release_year'=>'-1','max_runtime'=>'1 OR 1=1','content_type'=>'collection','limit'=>'0','page'=>'2','is_premium'=>'true','user_id'=>EDITOR,'territory'=>'LK','channel'=>'web','limit-array'=>['1']] as $key=>$value){
    $cases['invalid or forged parameter '.$key]=function()use($key,$value){$key=$key==='limit-array'?'limit':$key;$r=apiCall(apiWorld(),[$key=>$value]);apiAssert($r['status']===400);};
}
$cases['oversized query is rejected']=function(){apiAssert(apiCall(apiWorld(),['q'=>str_repeat('a',201)])['status']===400);};
$cases['malformed UTF8 is rejected']=function(){apiAssert(apiCall(apiWorld(),['q'=>"\xFF"] )['status']===400);};
$cases['SQL shaped search remains inert text']=function(){$r=apiCall(apiWorld(),['q'=>"' OR 1=1 --"]);apiAssert($r['status']===200&&apiIds($r)===[]);};
$cases['unsupported method is not a mutation']=function(){ $w=apiWorld();$r=apiCall($w,[],'POST');apiAssert($r['status']===405&&$r['headers']['Allow']==='GET'&&$w['repo']->reads===0); };
$cases['default limit and maximum limit validate']=function(){apiAssert(Query::parse([])->limit===20&&Query::parse(['limit'=>'50'])->limit===50&&apiCall(apiWorld(),['limit'=>'51'])['status']===400);};
foreach(['title_asc','title_desc','release_year_asc','release_year_desc'] as $sort)$cases['stable pagination with '.$sort]=function()use($sort){$records=[];foreach(['501','502','504','505','506'] as $id)$records[]=apiRecord('movie',$id,'Same Fictional Title');$w=apiWorld(null,$records);$cursor=null;$ids=[];do{$q=['resource'=>'movies','limit'=>'2','sort'=>$sort];if($cursor!==null)$q['cursor']=$cursor;$r=apiCall($w,$q);apiAssert($r['status']===200);array_push($ids,...apiIds($r));$cursor=$r['body']['data']['nextCursor'];}while($cursor!==null);apiAssert($ids===['501','502','504','505','506']&&count(array_unique($ids))===5);};
$cases['cursor signature tampering is rejected']=function(){ $w=apiWorld();$r=apiCall($w,['resource'=>'movies','limit'=>'1']);$token=$r['body']['data']['nextCursor'];apiAssert(apiCall($w,['resource'=>'movies','limit'=>'1','cursor'=>$token.'x'])['status']===400); };
$cases['cursor query binding prevents filter reuse']=function(){ $w=apiWorld();$t=apiCall($w,['resource'=>'movies','limit'=>'1'])['body']['data']['nextCursor'];apiAssert(apiCall($w,['resource'=>'movies','limit'=>'1','cursor'=>$t,'language'=>'en'])['status']===400); };
$cases['cursor cannot cross user context']=function(){ $w=apiWorld();$t=apiCall($w,['resource'=>'movies','limit'=>'1'])['body']['data']['nextCursor'];$w['contexts']->context=new Context(EDITOR,true,'LK',true,30,str_repeat('2',32));apiAssert(apiCall($w,['resource'=>'movies','limit'=>'1','cursor'=>$t])['status']===400); };
$cases['cursor expiry is enforced']=function(){ $w=apiWorld();$t=apiCall($w,['resource'=>'movies','limit'=>'1'])['body']['data']['nextCursor'];$w['clock']->time='2026-10-24T00:05:00Z';apiAssert(apiCall($w,['resource'=>'movies','limit'=>'1','cursor'=>$t])['status']===400); };
$cases['cursor contains only last visible public tuple']=function(){ $w=apiWorld();$t=apiCall($w,['resource'=>'movies','limit'=>'1'])['body']['data']['nextCursor'];$p=json_decode(base64_decode(strtr(explode('.',$t)[0],'-_','+/')),true);apiAssert($p['position']===['value'=>'Fictional Alpha','type'=>'movie','id'=>'501']&&!str_contains(json_encode($p),'Gamma')); };
foreach(['draft','pending_review','approved','rejected','unpublished','revoked'] as $state)$cases['nonpublic state '.$state.' is absent']=function()use($state){$r=apiRecord('movie','501','Hidden Fictional Title');$r['state']=$state;$w=apiWorld(null,[$r]);apiAssert(apiIds(apiCall($w,[]))===[]&&apiCall($w,['resource'=>'movies','id'=>'501'])['status']===404);};
foreach(['future'=>'2025-01-01T00:00:00Z','expired'=>'2027-01-01T00:00:00Z'] as $name=>$time)$cases[$name.' rights deny discovery']=function()use($time){$w=apiWorld();$w['clock']->time=$time;apiAssert(apiIds(apiCall($w,[]))===[]);};
$cases['grant revocation immediately affects subsequent requests']=function(){ $w=apiWorld();apiAssert(in_array('501',apiIds(apiCall($w,[])),true));foreach($w['repo']->records as &$r)if($r['metadata']['catalogue']['id']==='501')foreach($r['grants'] as &$g)$g['revoked']=true;unset($r,$g);apiAssert(!in_array('501',apiIds(apiCall($w,[])),true)); };
$cases['territory mismatch reveals no titles']=function(){ $w=apiWorld();$w['contexts']->context=new Context(null,true,'US',true,null,str_repeat('1',32));apiAssert(apiIds(apiCall($w,[]))===[]); };
$cases['unverified geographic context fails closed']=function(){ $w=apiWorld();$w['contexts']->context=new Context(null,true,'LK',false,null,str_repeat('1',32));apiAssert(apiCall($w,[])['status']===503&&$w['repo']->reads===0); };
$cases['missing trusted context fails closed']=function(){ $w=apiWorld();$w['contexts']->context=null;apiAssert(apiCall($w,[])['status']===503&&$w['repo']->reads===0); };
$cases['anonymous public access does not imply premium access']=function(){ $w=apiWorld();$a=apiCall($w,['resource'=>'availability','content_type'=>'movie','id'=>'501']);$b=apiCall($w,['resource'=>'availability','content_type'=>'movie','id'=>'502']);apiAssert($a['body']['data']['availability']['playbackEligible']&&!$b['body']['data']['availability']['playbackEligible']); };
$cases['verified own access grant can establish eligibility only']=function(){ $w=apiWorld();$w['contexts']->context=new Context(EDITOR,true,'LK',true,30,str_repeat('2',32));$r=apiCall($w,['resource'=>'availability','content_type'=>'movie','id'=>'502']);apiAssert($r['body']['data']['availability']['playbackEligible']&&!$r['body']['data']['availability']['playbackAvailable']); };
$cases['another user cannot reuse private grants']=function(){ $w=apiWorld();$w['contexts']->context=new Context(str_repeat('d',32),true,'LK',true,30,str_repeat('3',32));$r=apiCall($w,['resource'=>'availability','content_type'=>'movie','id'=>'502']);apiAssert(!$r['body']['data']['availability']['playbackEligible']);apiAssert(apiCall($w,['resource'=>'movies','id'=>'503'])['status']===404); };
$cases['inactive account is rejected before querying']=function(){ $w=apiWorld();$w['contexts']->context=new Context(EDITOR,false,'LK',true,30,str_repeat('2',32));apiAssert(apiCall($w,[])['status']===401&&$w['repo']->reads===0); };
$cases['missing access grant denies entitlement']=function(){ $w=apiWorld();$w['contexts']->context=new Context(EDITOR,true,'LK',true,30,str_repeat('2',32));$w['grants']->grants=[];$r=apiCall($w,['resource'=>'availability','content_type'=>'movie','id'=>'502']);apiAssert(!$r['body']['data']['availability']['playbackEligible']); };
$cases['trusted age restriction cannot use missing age evidence']=function(){ $w=apiWorld();$w['rules']->rules['movie:501:metadata']['minimum_age']=18;apiAssert(apiCall($w,['resource'=>'movies','id'=>'501'])['status']===404); };
$cases['authenticated-only metadata requires trusted identity']=function(){ $w=apiWorld();$w['rules']->rules['movie:501:metadata']['mode']='authenticated';apiAssert(apiCall($w,['resource'=>'movies','id'=>'501'])['status']===404);$w['contexts']->context=new Context(EDITOR,true,'LK',true,30,str_repeat('2',32));apiAssert(apiCall($w,['resource'=>'movies','id'=>'501'])['status']===200); };
$cases['unknown entitlement requirements deny metadata']=function(){ $w=apiWorld();unset($w['rules']->rules['movie:501:metadata']);apiAssert(apiCall($w,['resource'=>'movies','id'=>'501'])['status']===404); };
$cases['private and missing IDs return indistinguishable errors']=function(){ $w=apiWorld();$a=apiCall($w,['resource'=>'movies','id'=>'503']);$b=apiCall($w,['resource'=>'movies','id'=>'999']);apiAssert($a['status']===404&&$b['status']===404&&$a['body']['error']===$b['body']['error']); };
$cases['playback boundary never emits an origin or token']=function(){ $r=apiCall(apiWorld(),['resource'=>'playback','content_type'=>'movie','id'=>'501']);apiAssert($r['status']===503&&$r['body']['error']['code']==='PLAYBACK_NOT_CONFIGURED'&&!str_contains($r['raw'],'asset:')); };
$cases['preview eligibility is independent of full playback']=function(){ $w=apiWorld();$r=apiCall($w,['resource'=>'availability','content_type'=>'movie','id'=>'502']);$a=$r['body']['data']['availability'];apiAssert($a['previewEligible']&&!$a['playbackEligible']&&!$a['previewAvailable']); };
$cases['linked Shot requires a discoverable parent']=function(){ $w=apiWorld();$w['rules']->rules['movie:501:metadata']['mode']='grant';apiAssert(apiCall($w,['resource'=>'shots','id'=>'801'])['status']===404); };
$cases['series episode filter keeps its own availability']=function(){ $r=apiCall(apiWorld(),['resource'=>'episodes','parent_type'=>'series','parent_id'=>'601']);apiAssert(apiIds($r)===['701']); };
$cases['response allowlist excludes rights and storage fields']=function(){ $r=apiCall(apiWorld(),['resource'=>'movies','id'=>'501']);$d=$r['body']['data'];apiAssert(array_keys($d)===['id','contentType','title','synopsis','genre','language','releaseYear','runtimeSeconds','tags','availability']);foreach(['evidence','holder','storage_ref','provenance','verified_by','document','password','asset:'] as $key)apiAssert(!str_contains($r['raw'],$key)); };
$cases['JSON serialization is safe for HTML delimiter characters']=function(){ $json=Controller::encode(['title'=>'</script><img src=x>']);apiAssert(!str_contains($json,'<')&&json_decode($json,true)['title']==='</script><img src=x>'); };
$cases['private responses are never publicly cached']=function(){ $r=apiCall(apiWorld(),[]);apiAssert($r['headers']['Cache-Control']==='private, no-store'&&$r['headers']['Vary']==='Authorization, Cookie'&&$r['headers']['X-Content-Type-Options']==='nosniff'); };
$cases['server creates a new correlation identifier per request']=function(){ $w=apiWorld();$a=apiCall($w);$b=apiCall($w);apiAssert($a['body']['requestId']!==$b['body']['requestId']&&preg_match('/^[a-f0-9]{32}$/D',$a['body']['requestId'])===1); };
$cases['backend failure returns no implementation details']=function(){ $w=apiWorld();$w['repo']->fail=true;$r=apiCall($w);apiAssert($r['status']===503&&!str_contains($r['raw'],'SELECT')&&!str_contains($r['raw'],'PDO')); };
$cases['fixed window limiter bounds repeated invalid ID requests']=function(){ $w=apiWorld();$limiter=new FixedWindowLimiter(2);$w['controller']=new Controller($w['service'],$w['contexts'],$limiter,$w['clock']);apiAssert(apiCall($w,['id'=>'bad'])['status']===400);apiAssert(apiCall($w,['id'=>'bad'])['status']===400);$r=apiCall($w,['id'=>'bad']);apiAssert($r['status']===429&&(int)$r['headers']['Retry-After']>0); };
$cases['limiter window expiry allows a new request']=function(){ $w=apiWorld();$w['controller']=new Controller($w['service'],$w['contexts'],new FixedWindowLimiter(1),$w['clock']);apiAssert(apiCall($w)['status']===200&&apiCall($w)['status']===429);$w['clock']->time='2026-10-24T00:01:00Z';apiAssert(apiCall($w)['status']===200); };
$cases['candidate budget never returns hidden positions or partial results']=function(){ $records=[];for($i=1000;$i<1202;$i++){$r=apiRecord('movie',(string)$i,'Hidden '.(string)$i);foreach($r['grants'] as &$g)$g['revoked']=true;unset($g);$records[]=$r;}$r=apiCall(apiWorld(null,$records));apiAssert($r['status']===503&&!isset($r['body']['data'])); };

$cases['expired user grant denies access while distribution rights remain valid']=function(){ $w=apiWorld();$w['contexts']->context=new Context(EDITOR,true,'LK',true,30,str_repeat('2',32));foreach($w['grants']->grants as &$end)$end='2026-10-23T00:00:00Z';unset($end);$r=apiCall($w,['resource'=>'availability','content_type'=>'movie','id'=>'502']);apiAssert($r['status']===200&&!$r['body']['data']['availability']['playbackEligible']); };
$cases['user grant is bound to territory independently of licence']=function(){ $w=apiWorld();foreach($w['repo']->records as &$r){$r['publication']['territories'][]='US';foreach($r['grants'] as &$g)$g['territories'][]='US';unset($g);}unset($r);$w['contexts']->context=new Context(EDITOR,true,'US',true,30,str_repeat('2',32));$r=apiCall($w,['resource'=>'availability','content_type'=>'movie','id'=>'502']);apiAssert($r['status']===200&&$r['body']['data']['availability']['discoverable']&&!$r['body']['data']['availability']['playbackEligible']); };
$cases['missing rights deny discovery despite valid user grants']=function(){ $w=apiWorld();foreach($w['repo']->records as &$r)$r['grants']=[];unset($r);apiAssert(apiIds(apiCall($w))===[]); };
$cases['untrusted exception reasons are never public error codes']=function(){ $w=apiWorld();$provider=new class implements \Zinema\Catalogue\ContextProvider {public function resolve():?Context {throw new \Zinema\Catalogue\ApiFailure(503,'SELECT fictional_private_table');}};$controller=new Controller($w['service'],$provider,$w['limiter'],$w['clock']);$r=$controller->handle('GET',[]);apiAssert($r->status===500&&!str_contains($r->body,'SELECT')&&str_contains($r->body,'INTERNAL_ERROR')); };
$cases['response byte cap returns no partial records']=function(){ $records=[];for($i=1000;$i<1050;$i++){$r=apiRecord('movie',(string)$i,'Fictional large response '.$i);$r['metadata']['synopsis']=str_repeat('s',6000);$records[]=$r;}$r=apiCall(apiWorld(null,$records),['limit'=>'50']);apiAssert($r['status']===503&&$r['body']['error']['code']==='RESPONSE_LIMIT_EXCEEDED'&&!isset($r['body']['data'])); };
$cases['limiter capacity cannot evict another identity quota']=function(){ $w=apiWorld();$limiter=new FixedWindowLimiter(1,60,1);$w['controller']=new Controller($w['service'],$w['contexts'],$limiter,$w['clock']);apiAssert(apiCall($w)['status']===200);$w['contexts']->context=new Context(null,true,'LK',true,null,str_repeat('2',32));apiAssert(apiCall($w)['status']===429);$w['contexts']->context=new Context(null,true,'LK',true,null,str_repeat('1',32));apiAssert(apiCall($w)['status']===429); };
$cases['raw oversized query rejects before repository use']=function(){ $w=apiWorld();$r=$w['controller']->handle('GET',[],4097);apiAssert($r->status===400&&$w['repo']->reads===0); };
$cases['malformed persisted rights aggregate fails closed']=function(){try{\Zinema\Catalogue\Record::decode(['document'=>'{}']);throw new RuntimeException();}catch(\Zinema\Catalogue\ApiFailure $e){apiAssert($e->reason==='CATALOGUE_UNAVAILABLE');}};

$cases['limiter refuses clock rollback rather than resetting quota']=function(){ $w=apiWorld();apiAssert(apiCall($w)['status']===200);$w['clock']->time='2026-10-23T23:59:59Z';$r=apiCall($w);apiAssert($r['status']===503&&$r['body']['error']['code']==='CONTEXT_UNAVAILABLE'); };
try{$name=$argv[1]??'';if($name==='list'){echo json_encode(array_keys($cases));exit;}if(!isset($cases[$name]))throw new RuntimeException();$cases[$name]();echo '{"passed":true}';}
catch(Throwable $e){fwrite(STDERR,json_encode(['error'=>$e instanceof \Zinema\Catalogue\ApiFailure?$e->reason:'API_ASSERTION_FAILED','valuesRedacted'=>true]));exit(1);}
